import { Component, ViewChild, OnDestroy, ChangeDetectorRef, AfterViewInit } from '@angular/core';
import { RequestsState } from 'app/services/requests-state';
import { ReputationService } from 'app/services/reputation';
import { PermissionsService } from 'app/services/permissions';
import { Product } from '@imunify360-api/license';
import { LicenseState } from 'app/services/license-state';
import { LoaderDirective } from 'app/utils/loader/loader.directive';
import { combineLatest, Subject, takeUntil } from 'rxjs';


@Component({
    selector: 'reputation',
    styleUrls: ['./reputation.component.scss'],
    templateUrl: './reputation.component.html',
    host: {
        class: 'display-flex-column',
        '[style.min-height.px]': '400', // initial height for loader
    },
})
export class ReputationComponent implements OnDestroy, AfterViewInit {
    @ViewChild(LoaderDirective, {static: true}) loader: LoaderDirective;

    Product = Product;
    isAvailable: boolean | null = null;
    private destroy$ = new Subject<void>();
    constructor(
        private cdr: ChangeDetectorRef,
        public requestsState: RequestsState,
        public reputationService: ReputationService,
        private permissions: PermissionsService,
        private licenseState: LicenseState,
    ) {}

    ngAfterViewInit() {
        this.checkIsAvailable();
    }

    ngOnDestroy() {
        this.destroy$.next();
    }

    defaultTranslation(type: string) {
        // no optimization since it is very rare case
        return type[0].toUpperCase() + type.slice(1).toLowerCase().replace(/_/g, ' ');
    }

    private checkIsAvailable(): void {
        const  loaderName = 'reputation_management_tab';
        this.loader?.show(loaderName);
        combineLatest([this.permissions.MS_ON_DEMAND_SCAN, this.licenseState.license])
            .pipe(takeUntil(this.destroy$))
            .subscribe({
                next: results => {
                    const [MS_ON_DEMAND_SCAN, license] = results;
                    this.isAvailable = MS_ON_DEMAND_SCAN && !license?.isFreeVersion;
                    this.loader?.hide(loaderName);
                    this.cdr.markForCheck();
                },
                error: () => {
                    this.isAvailable = false;
                    this.loader?.hide(loaderName);
                    this.cdr.markForCheck();
                }
            });
    }
}
